def max_performance(n, speed, efficiency, k):
    MOD = 10 ** 9 + 7
    best = 0

    def backtrack(start, chosen):
        nonlocal best
        if chosen:
            total_speed = sum(speed[i] for i in chosen)
            min_eff = min(efficiency[i] for i in chosen)
            best = max(best, total_speed * min_eff)
        if len(chosen) == k or start == n:
            return
        for i in range(start, n):
            backtrack(i + 1, chosen + [i])

    backtrack(0, [])
    return best % MOD


if __name__ == "__main__":
    print(max_performance(6, [2, 10, 3, 1, 5, 8], [5, 4, 3, 9, 7, 2], 2))
    print(max_performance(6, [2, 10, 3, 1, 5, 8], [5, 4, 3, 9, 7, 2], 3))

