import java.util.*;

public class Main {
    static int n, k;
    static int[] speed, efficiency;
    static long best;
    static final long MOD = 1000000007L;

    static int maxPerformance(int nEng, int[] spd, int[] eff, int kLimit) {
        n = nEng; speed = spd; efficiency = eff; k = kLimit; best = 0;
        backtrack(0, new ArrayList<>());
        return (int) (best % MOD);
    }

    static void backtrack(int start, List<Integer> chosen) {
        if (!chosen.isEmpty()) {
            long totalSpeed = 0;
            int minEff = Integer.MAX_VALUE;
            for (int i : chosen) {
                totalSpeed += speed[i];
                minEff = Math.min(minEff, efficiency[i]);
            }
            best = Math.max(best, totalSpeed * minEff);
        }
        if (chosen.size() == k || start == n) return;
        for (int i = start; i < n; i++) {
            chosen.add(i);
            backtrack(i + 1, chosen);
            chosen.remove(chosen.size() - 1);
        }
    }

    public static void main(String[] args) {
        System.out.println(maxPerformance(6, new int[]{2, 10, 3, 1, 5, 8}, new int[]{5, 4, 3, 9, 7, 2}, 2));
        System.out.println(maxPerformance(6, new int[]{2, 10, 3, 1, 5, 8}, new int[]{5, 4, 3, 9, 7, 2}, 3));
    }
}

