import java.util.*;

public class Main {
    static int maxPerformance(int n, int[] speed, int[] efficiency, int k) {
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> efficiency[b] - efficiency[a]);

        PriorityQueue<Integer> heap = new PriorityQueue<>();
        long speedSum = 0;
        long best = 0;
        final long MOD = 1000000007L;

        for (int i : idx) {
            heap.add(speed[i]);
            speedSum += speed[i];
            if (heap.size() > k) {
                speedSum -= heap.poll();
            }
            best = Math.max(best, speedSum * efficiency[i]);
        }
        return (int) (best % MOD);
    }

    public static void main(String[] args) {
        System.out.println(maxPerformance(6, new int[]{2, 10, 3, 1, 5, 8}, new int[]{5, 4, 3, 9, 7, 2}, 2));
        System.out.println(maxPerformance(6, new int[]{2, 10, 3, 1, 5, 8}, new int[]{5, 4, 3, 9, 7, 2}, 3));
    }
}

